      const mode  = pendingLoseMode;
      pendingLoseScore = null;
      pendingLoseMode  = null;
      $loseNameBlock.classList.remove('show');
      $loseScoreRank.textContent = 'Submitting\u2026';
      $loseScoreBadge.style.display = '';
      const result = await lbSubmit(mode, name, score);
